interface ParsedForecast {
  time: Date;
  timestamp: number;
  probability: number; // 0-100
  intensity: 'none' | 'light' | 'moderate' | 'heavy';
  amount: number; // inches
  temperature: number;
  description: string;
}

interface RainCheckResponse {
  location: string;
  lat: number;
  lon: number;
  forecast: ParsedForecast[]; // 8 data points for 24 hours
}

function classifyIntensity(amountMm: number): 'none' | 'light' | 'moderate' | 'heavy' {
  if (amountMm === 0) return 'none';
  if (amountMm < 2.5) return 'light';  // 3-hour period
  if (amountMm < 7.6) return 'moderate'; // 3-hour period
  return 'heavy';
}

